"use server";

import readingTime from "reading-time";
import { BlogPost } from "@/lib/blog-post";
import { revalidatePath } from "next/cache";
import { z } from "zod";

import { auth } from "@/auth";
import { ContactMessage } from "@/lib/contact-message";
import { getPostBySlug, type BlogPostStatus } from "@/lib/mdx";
import dbConnect from "@/lib/mongodb";
import { Subscriber } from "@/lib/subscriber";

const affiliateLinkSchema = z.object({
  label: z.string().trim().min(1),
  url: z.string().trim().url(),
  disclosure: z.string().trim().min(1),
});

const postSaveSchema = z.object({
  originalSlug: z.string().trim().optional(),
  title: z.string().trim().min(3),
  slug: z
    .string()
    .trim()
    .min(3)
    .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  category: z.string().trim().min(1),
  excerpt: z.string().trim().min(10).max(500),
  coverImage: z.string().trim().min(1),
  author: z.string().trim().min(1),
  featured: z.boolean(),
  status: z.enum(["draft", "published", "scheduled"]),
  publishDate: z.string().trim().optional(),
  scheduledAt: z.string().trim().optional(),
  tags: z.array(z.string().trim().min(1)).default([]),
  content: z.string().trim().min(50),
  affiliateLinks: z.array(affiliateLinkSchema).default([]),
}).superRefine((input, ctx) => {
  if (input.status === "scheduled" && !input.scheduledAt?.trim()) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      path: ["scheduledAt"],
      message: "Scheduled posts require a schedule date.",
    });
  }
});

export type PostSaveInput = z.infer<typeof postSaveSchema>;

const subscriberUpdateSchema = z
  .object({
    id: z.string().trim().min(1),
    email: z.string().trim().email(),
    blogUpdates: z.boolean(),
    promotions: z.boolean(),
  })
  .superRefine((input, ctx) => {
    if (!input.blogUpdates && !input.promotions) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ["blogUpdates"],
        message: "Select at least one subscription type.",
      });
    }
  });

async function ensureAdmin() {
  const session = await auth();

  if (!session?.user?.email) {
    throw new Error("Unauthorized");
  }

  return session;
}

function slugifyHeading(value: string) {
  return value
    .toLowerCase()
    .trim()
    .replace(/[`~!@#$%^&*()+=,[\]{}|\\:;"'<>,.?/]/g, "")
    .replace(/\s+/g, "-");
}

function extractHeadings(content: string) {
  const headings: {
  id: string;
  text: string;
  level: number;
}[] = [];
  const lines = content.split("\n");

  for (const line of lines) {
    const match = /^(##|###)\s+(.*)$/.exec(line.trim());

    if (!match) continue;

    headings.push({
      id: slugifyHeading(match[2]),
      text: match[2],
      level: match[1].length,
    });
  }

  return headings;
}

function revalidatePostRoutes(slug: string) {
  revalidatePath("/");
  revalidatePath("/blog");
  revalidatePath(`/blog/${slug}`);
  revalidatePath("/blog/[slug]", "page");
  revalidatePath("/admin/dashboard");
  revalidatePath("/admin/manage-posts");
  revalidatePath("/admin/new-post");
}

function revalidateSubscriberRoutes() {
  revalidatePath("/admin/subscribers");
}

export async function savePostAction(input: PostSaveInput) {
  await ensureAdmin();

  const parsed = postSaveSchema.safeParse(input);

  if (!parsed.success) {
    throw new Error("Invalid post data.");
  }

  const data = parsed.data;

  await dbConnect();

  const existing = await BlogPost.findOne({
    slug: data.originalSlug ?? data.slug,
  });

  const slugTaken = await BlogPost.findOne({
    slug: data.slug,
    ...(existing ? { _id: { $ne: existing._id } } : {}),
  });

  if (slugTaken) {
    throw new Error("A post with this slug already exists.");
  }

  const scheduledAt = data.scheduledAt
    ? new Date(data.scheduledAt)
    : null;

  if (scheduledAt && Number.isNaN(scheduledAt.getTime())) {
    throw new Error("Invalid schedule date.");
  }

  const manualPublishDate = data.publishDate ? new Date(data.publishDate) : null;

  if (manualPublishDate && Number.isNaN(manualPublishDate.getTime())) {
    throw new Error("Invalid publish date.");
  }

  const publishedAt =
    data.status === "published"
      ? manualPublishDate ?? existing?.publishedAt ?? new Date()
      : data.status === "scheduled"
      ? scheduledAt
      : existing?.publishedAt ?? null;

  const coverImage = data.coverImage.trim();

  const payload = {
    title: data.title,
    slug: data.slug,
    excerpt: data.excerpt,
    content: data.content,
    coverImage,
    author: data.author,
    category: data.category,
    tags: data.tags,
    featured: data.featured,
    status: data.status,
    scheduledAt,
    publishedAt,
    readTime: readingTime(data.content).text,
    headings: extractHeadings(data.content),
    affiliateLinks: data.affiliateLinks,
  };

  if (existing) {
    Object.assign(existing, payload);
    await existing.save();
  } else {
    await BlogPost.create(payload);
  }

  revalidatePostRoutes(data.slug);

  return {
    slug: data.slug,
    status: data.status,
  };
}

export async function deletePostAction(slug: string) {
  await ensureAdmin();

  await dbConnect();

  await BlogPost.deleteOne({
    slug,
  });

  revalidatePostRoutes(slug);
}

export async function togglePostStatusAction(slug: string) {
  await ensureAdmin();

  await dbConnect();

  const post = await BlogPost.findOne({ slug });

  if (!post) {
    throw new Error("Post not found.");
  }

  const isPublishedLike =
    post.status === "published" ||
    (post.status === "scheduled" &&
      post.scheduledAt instanceof Date &&
      post.scheduledAt.getTime() <= Date.now());

  post.status =
    isPublishedLike
      ? "draft"
      : "published";

  if (post.status === "published") {
    post.publishedAt = new Date();
    post.scheduledAt = null;
  } else {
    post.scheduledAt = null;
  }

  await post.save();

  revalidatePostRoutes(slug);
}

export async function markMessageAsReadAction(id: string) {
  await ensureAdmin();
  await dbConnect();
  await ContactMessage.findByIdAndUpdate(id, { status: "read" }).exec();
  revalidatePath("/admin/dashboard");
  revalidatePath("/admin/contact-messages");
}

export async function deleteMessageAction(id: string) {
  await ensureAdmin();
  await dbConnect();
  await ContactMessage.findByIdAndDelete(id).exec();
  revalidatePath("/admin/dashboard");
  revalidatePath("/admin/contact-messages");
}

export async function deleteMessagesBulkAction(ids: string[]) {
  await ensureAdmin();
  await dbConnect();
  await ContactMessage.deleteMany({ _id: { $in: ids } }).exec();
  revalidatePath("/admin/dashboard");
  revalidatePath("/admin/contact-messages");
}

export async function updateSubscriberAction(
  input: z.infer<typeof subscriberUpdateSchema>,
) {
  await ensureAdmin();

  const parsed = subscriberUpdateSchema.safeParse(input);

  if (!parsed.success) {
    throw new Error("Invalid subscriber data.");
  }

  await dbConnect();

  const data = parsed.data;
  const normalizedEmail = data.email.toLowerCase();
  const existingSubscriber = await Subscriber.findById(data.id);

  if (!existingSubscriber) {
    throw new Error("Subscriber not found.");
  }

  const emailTaken = await Subscriber.findOne({
    email: normalizedEmail,
    _id: { $ne: data.id },
  }).lean();

  if (emailTaken) {
    throw new Error("A subscriber with this email already exists.");
  }

  existingSubscriber.email = normalizedEmail;
  existingSubscriber.blogUpdates = data.blogUpdates;
  existingSubscriber.promotions = data.promotions;

  await existingSubscriber.save();

  revalidateSubscriberRoutes();
}

export async function deleteSubscriberAction(id: string) {
  await ensureAdmin();
  await dbConnect();
  await Subscriber.findByIdAndDelete(id).exec();
  revalidateSubscriberRoutes();
}

export async function deleteSubscribersBulkAction(ids: string[]) {
  await ensureAdmin();
  await dbConnect();
  await Subscriber.deleteMany({ _id: { $in: ids } }).exec();
  revalidateSubscriberRoutes();
}

"use client";

import { useEffect, useMemo, useRef, useState, useTransition } from "react";
import Image from "next/image";
import { useRouter } from "next/navigation";
import {
  Bold,
  Code,
  Heading2,
  Heading3,
  Image as ImageIcon,
  Italic,
  Link2,
  MonitorPlay,
  Save,
  SquareTerminal,
  Star,
  Upload,
} from "lucide-react";

import { savePostAction, type PostSaveInput } from "@/app/(admin)/admin/actions";
import type { BlogPost } from "@/lib/mdx";

type PostEditorProps = {
  initialPost: BlogPost | null;
};

type EditableAffiliateLink = {
  id: string;
  label: string;
  url: string;
  disclosure: string;
};

type ToastState =
  | {
      type: "success" | "error";
      message: string;
    }
  | null;

const PREDEFINED_CATEGORIES = [
  "Next.js",
  "React",
  "MERN",
  "AI Tools",
  "Freelancing",
  "SaaS",
  "Tools",
] as const;

function slugify(value: string) {
  return value
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-");
}

function getWordCount(value: string) {
  return value.trim() ? value.trim().split(/\s+/).length : 0;
}

function getReadTime(value: string) {
  return `${Math.max(1, Math.ceil(getWordCount(value) / 200))} min read`;
}

function toDateTimeLocalValue(value?: string) {
  if (!value) {
    return "";
  }

  const parsed = new Date(value);

  if (Number.isNaN(parsed.getTime())) {
    return value;
  }

  const localDate = new Date(parsed.getTime() - parsed.getTimezoneOffset() * 60_000);
  return localDate.toISOString().slice(0, 16);
}

function createAffiliateLink(
  value: Partial<Omit<EditableAffiliateLink, "id">> = {},
): EditableAffiliateLink {
  const cryptoObject =
    typeof globalThis !== "undefined" && "crypto" in globalThis ? globalThis.crypto : undefined;
  const randomUuid =
    typeof cryptoObject?.randomUUID === "function"
      ? cryptoObject.randomUUID.bind(cryptoObject)
      : undefined;

  return {
    id: randomUuid?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`,
    label: value.label ?? "",
    url: value.url ?? "",
    disclosure: value.disclosure ?? "",
  };
}

function renderInline(value: string) {
  const segments = value.split(/(\*\*.*?\*\*|`.*?`|\*.*?\*|\[.*?\]\(.*?\))/g);

  return segments.map((segment, index) => {
    if (segment.startsWith("**") && segment.endsWith("**")) {
      return <strong key={index}>{segment.slice(2, -2)}</strong>;
    }

    if (segment.startsWith("`") && segment.endsWith("`")) {
      return (
        <code
          key={index}
          className="rounded bg-[#0f172a] px-1.5 py-0.5 text-sm text-emerald-200"
        >
          {segment.slice(1, -1)}
        </code>
      );
    }

    if (segment.startsWith("*") && segment.endsWith("*")) {
      return <em key={index}>{segment.slice(1, -1)}</em>;
    }

    const linkMatch = /^\[(.*?)\]\((.*?)\)$/.exec(segment);

    if (linkMatch) {
      return (
        <a
          key={index}
          href={linkMatch[2]}
          target="_blank"
          rel="noreferrer"
          className="font-medium text-primary underline underline-offset-4"
        >
          {linkMatch[1]}
        </a>
      );
    }

    return <span key={index}>{segment}</span>;
  });
}

function PreviewPane({ content }: { content: string }) {
  const lines = content.split("\n");
  const elements: React.ReactNode[] = [];
  let paragraphBuffer: string[] = [];
  let codeBuffer: string[] = [];
  let inCodeBlock = false;

  function flushParagraph() {
    if (!paragraphBuffer.length) {
      return;
    }

    const value = paragraphBuffer.join(" ").trim();

    if (value) {
      elements.push(
        <p key={`p-${elements.length}`} className="text-sm leading-7 text-white/75">
          {renderInline(value)}
        </p>,
      );
    }

    paragraphBuffer = [];
  }

  function flushCodeBlock() {
    if (!codeBuffer.length) {
      return;
    }

    elements.push(
      <pre
        key={`code-${elements.length}`}
        className="overflow-x-auto rounded-xl border border-white/10 bg-[#0b1020] p-4 text-xs text-emerald-200"
      >
        <code>{codeBuffer.join("\n")}</code>
      </pre>,
    );

    codeBuffer = [];
  }

  for (const line of lines) {
    if (line.trim().startsWith("```")) {
      flushParagraph();
      if (inCodeBlock) {
        flushCodeBlock();
      }
      inCodeBlock = !inCodeBlock;
      continue;
    }

    if (inCodeBlock) {
      codeBuffer.push(line);
      continue;
    }

    if (!line.trim()) {
      flushParagraph();
      continue;
    }

    if (line.startsWith("### ")) {
      flushParagraph();
      elements.push(
        <h3 key={`h3-${elements.length}`} className="text-lg font-semibold text-white">
          {line.replace(/^###\s+/, "")}
        </h3>,
      );
      continue;
    }

    if (line.startsWith("## ")) {
      flushParagraph();
      elements.push(
        <h2 key={`h2-${elements.length}`} className="text-2xl font-semibold text-white">
          {line.replace(/^##\s+/, "")}
        </h2>,
      );
      continue;
    }

    const imageMatch = /^!\[(.*?)\]\((.*?)\)$/.exec(line.trim());

    if (imageMatch) {
      flushParagraph();
      elements.push(
        <div
          key={`img-${elements.length}`}
          className="rounded-xl border border-white/10 bg-white/5 p-4 text-sm text-white/60"
        >
          Image preview: {imageMatch[1] || "Untitled"} ({imageMatch[2]})
        </div>,
      );
      continue;
    }

    if (line.trim().startsWith("<AffiliateLink")) {
      flushParagraph();
      const label = /label="(.*?)"/.exec(line)?.[1] ?? "Affiliate Tool";
      const url = /url="(.*?)"/.exec(line)?.[1] ?? "#";
      const disclosure =
        /disclosure="(.*?)"/.exec(line)?.[1] ?? "Affiliate link disclosure";

      elements.push(
        <div
          key={`affiliate-${elements.length}`}
          className="rounded-xl border border-primary/20 bg-primary/10 p-4 text-sm"
        >
          <p className="font-semibold text-white">Affiliate recommendation: {label}</p>
          <p className="mt-2 text-white/70">Link: {url}</p>
          <p className="mt-2 text-xs text-white/55">{disclosure}</p>
        </div>,
      );
      continue;
    }

    paragraphBuffer.push(line.trim());
  }

  flushParagraph();
  flushCodeBlock();

  if (!elements.length) {
    return (
      <div className="flex min-h-[420px] items-center justify-center rounded-xl border border-dashed border-white/10 bg-[#0b1020] px-6 text-center text-sm text-white/45">
        Start writing MDX to see a live preview.
      </div>
    );
  }

  return <div className="space-y-5">{elements}</div>;
}

export function PostEditor({ initialPost }: PostEditorProps) {
  const router = useRouter();
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isPending, startTransition] = useTransition();
  const [toast, setToast] = useState<ToastState>(null);
  const [title, setTitle] = useState(initialPost?.title ?? "");
  const [slug, setSlug] = useState(initialPost?.slug ?? "");
  const [slugTouched, setSlugTouched] = useState(Boolean(initialPost?.slug));
  const [category, setCategory] = useState(initialPost?.category ?? PREDEFINED_CATEGORIES[0]);
  const [isCustomCategory, setIsCustomCategory] = useState(
    initialPost?.category ? !PREDEFINED_CATEGORIES.includes(initialPost.category as any) : false,
  );
  const [excerpt, setExcerpt] = useState(initialPost?.excerpt ?? "");
  const [coverImage, setCoverImage] = useState(initialPost?.coverImage ?? "");
  const [author, setAuthor] = useState(initialPost?.author ?? "Zeeshan Zakir");
  const [featured, setFeatured] = useState(initialPost?.featured ?? false);
  const [status, setStatus] = useState<"draft" | "published" | "scheduled">(
    initialPost?.status ?? "draft",
  );
  const [publishDate, setPublishDate] = useState(toDateTimeLocalValue(initialPost?.date));
  const [scheduledAt, setScheduledAt] = useState(toDateTimeLocalValue(initialPost?.scheduledAt));
  const [tags, setTags] = useState(initialPost?.tags.join(", ") ?? "");
  const [content, setContent] = useState(initialPost?.content ?? "");
  const [isUploading, setIsUploading] = useState(false);
  const [affiliateLinks, setAffiliateLinks] = useState<EditableAffiliateLink[]>(() =>
    initialPost?.affiliateLinks.length
      ? initialPost.affiliateLinks.map((link) => createAffiliateLink(link))
      : [createAffiliateLink()],
  );

  useEffect(() => {
    if (!toast) {
      return;
    }

    const timeout = window.setTimeout(() => setToast(null), 3500);
    return () => window.clearTimeout(timeout);
  }, [toast]);

  const wordCount = useMemo(() => getWordCount(content), [content]);
  const readTime = useMemo(() => getReadTime(content), [content]);

  async function handleImageUpload(event: React.ChangeEvent<HTMLInputElement>, target: "cover" | "content") {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const formData = new FormData();
    formData.append("file", file);

    try {
      const response = await fetch("/api/upload", {
        method: "POST",
        body: formData,
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || "Failed to upload image");
      }

      if (target === "cover") {
        setCoverImage(result.url);
      } else {
        insertSnippet(`![${file.name}](${result.url})`, "", "");
      }

      setToast({ type: "success", message: "Image uploaded successfully" });
    } catch (error) {
      setToast({
        type: "error",
        message: error instanceof Error ? error.message : "Failed to upload image",
      });
    } finally {
      setIsUploading(false);
      // Clear input
      event.target.value = "";
    }
  }

  function updateAffiliateLink(
    id: string,
    field: "label" | "url" | "disclosure",
    value: string,
  ) {
    setAffiliateLinks((current) =>
      current.map((link) => (link.id === id ? { ...link, [field]: value } : link)),
    );
  }

  function insertSnippet(before: string, after = "", placeholder = "text") {
    const element = textareaRef.current;

    if (!element) {
      return;
    }

    const start = element.selectionStart;
    const end = element.selectionEnd;
    const selected = content.slice(start, end) || placeholder;
    const nextValue =
      content.slice(0, start) + before + selected + after + content.slice(end);

    setContent(nextValue);

    requestAnimationFrame(() => {
      element.focus();
      const cursor = start + before.length + selected.length + after.length;
      element.setSelectionRange(cursor, cursor);
    });
  }

  function handleToolbarInsert(type: string) {
    if (type === "h2") {
      insertSnippet("## ", "", "Heading");
      return;
    }

    if (type === "h3") {
      insertSnippet("### ", "", "Heading");
      return;
    }

    if (type === "bold") {
      insertSnippet("**", "**", "bold text");
      return;
    }

    if (type === "italic") {
      insertSnippet("*", "*", "italic text");
      return;
    }

    if (type === "code") {
      insertSnippet("`", "`", "code");
      return;
    }

    if (type === "code-block") {
      insertSnippet("```ts\n", "\n```", "const example = true;");
      return;
    }

    if (type === "link") {
      const url = window.prompt("Enter the link URL:", "https://");
      if (!url) return;
      insertSnippet("[", `](${url})`, "Link text");
      return;
    }

    if (type === "image") {
      const url = window.prompt("Enter the image URL:", "/images/blog/example.svg");
      if (!url) return;
      insertSnippet("![", `](${url})`, "Image alt text");
      return;
    }

    if (type === "upload") {
      fileInputRef.current?.click();
      return;
    }

    if (type === "affiliate") {
      const label = window.prompt("Tool name:", "Cursor");
      const url = window.prompt("Affiliate URL:", "https://example.com");
      const disclosure = window.prompt(
        "Disclosure text:",
        "Affiliate link - I may earn a commission at no extra cost to you.",
      );

      if (!label || !url || !disclosure) {
        return;
      }

      insertSnippet(
        `<AffiliateLink label="${label}" url="${url}" disclosure="${disclosure}" />`,
        "",
        "",
      );
      return;
    }

    if (type === "ads") {
      insertSnippet("{/* AdSense placeholder */}", "", "");
    }
  }

  async function persistPost(nextStatus: "draft" | "published" | "scheduled") {
    const payload: PostSaveInput = {
      originalSlug: initialPost?.slug ?? undefined,
      title: title.trim(),
      slug: slug.trim(),
      category,
      excerpt: excerpt.trim(),
      coverImage: coverImage.trim() || "/images/blog/default-cover.svg",
      author: author.trim() || "Zeeshan Zakir",
      featured,
      status: nextStatus,
      publishDate: publishDate || undefined,
      scheduledAt: nextStatus === "scheduled" ? scheduledAt : undefined,
      tags: tags
        .split(",")
        .map((tag) => tag.trim())
        .filter(Boolean),
      content,
      affiliateLinks: affiliateLinks
        .filter((link) => link.label || link.url || link.disclosure)
        .map(({ label, url, disclosure }) => ({
          label,
          url,
          disclosure,
        })),
    };

    startTransition(async () => {
      try {
        const result = await savePostAction(payload);
        setStatus(result.status);
        setToast({
          type: "success",
          message:
            result.status === "published"
              ? "Post published successfully."
              : "Draft saved successfully.",
        });
        router.replace(`/admin/new-post?slug=${result.slug}`);
        router.refresh();
      } catch (error) {
        setToast({
          type: "error",
          message:
            error instanceof Error ? error.message : "Unable to save the post.",
        });
      }
    });
  }

  function openPreview() {
    if (!slug.trim()) {
      setToast({
        type: "error",
        message: "Add a title first so a slug can be generated.",
      });
      return;
    }

    window.open(`/blog/${slug}`, "_blank", "noopener,noreferrer");
  }

  const toolbarButtons = [
    { type: "h2", label: "H2", icon: Heading2 },
    { type: "h3", label: "H3", icon: Heading3 },
    { type: "bold", label: "Bold", icon: Bold },
    { type: "italic", label: "Italic", icon: Italic },
    { type: "code", label: "Code", icon: Code },
    { type: "code-block", label: "Code Block", icon: SquareTerminal },
    { type: "link", label: "Link", icon: Link2 },
    { type: "image", label: "Image URL", icon: ImageIcon },
    { type: "upload", label: "Upload Image", icon: Upload },
    { type: "affiliate", label: "Affiliate", icon: Star },
    { type: "ads", label: "AdSense", icon: MonitorPlay },
  ] as const;

  return (
    <div className="space-y-6">
      <input
        ref={fileInputRef}
        type="file"
        className="hidden"
        accept="image/*"
        onChange={(e) => handleImageUpload(e, "content")}
        disabled={isUploading}
      />
      {toast ? (
        <div
          className={`rounded-xl px-4 py-3 text-sm font-medium ${
            toast.type === "success"
              ? "bg-emerald-500/15 text-emerald-200"
