"use client";

import { useState, useMemo, JSX } from "react";
import {
  explainRegex,
  FLAGS,
  COMMON_PATTERNS,
  SAMPLE_PATTERN,
  SAMPLE_TEXT,
  type CommonPattern,
} from "@/lib/regex-tester";

export function RegexTesterTool() {
  const [pattern, setPattern] = useState(SAMPLE_PATTERN);
  const [flags, setFlags] = useState<string[]>(["g"]);
  const [testText, setTestText] = useState(SAMPLE_TEXT);
  const [error, setError] = useState<string | null>(null);

  const regex = useMemo(() => {
    try {
      const reg = new RegExp(pattern, flags.join(""));
      setError(null);
      return reg;
    } catch (e) {
      setError(e instanceof Error ? e.message : "Invalid regex");
      return null;
    }
  }, [pattern, flags]);

  const matches = useMemo(() => {
    if (!regex) return [];
    const found: RegExpExecArray[] = [];
    let match: RegExpExecArray | null;
    const global = flags.includes("g");
    if (global) {
      while ((match = regex.exec(testText)) !== null) {
        found.push(match);
        if (match[0].length === 0) regex.lastIndex++;
      }
    } else {
      match = regex.exec(testText);
      if (match) found.push(match);
    }
    return found;
  }, [regex, testText, flags]);

  const explanations = useMemo(() => explainRegex(pattern), [pattern]);

  const toggleFlag = (flag: string) => {
    setFlags((prev) =>
      prev.includes(flag) ? prev.filter((f) => f !== flag) : [...prev, flag]
    );
  };

  const loadPattern = (p: CommonPattern) => {
    setPattern(p.pattern);
    setFlags(p.flags ? p.flags.split("") : []);
  };

  const highlightText = () => {
    if (!regex || matches.length === 0) {
      return <span>{testText}</span>;
    }

    const parts: JSX.Element[] = [];
    let lastIndex = 0;

    matches.forEach((match, idx) => {
      if (match.index! > lastIndex) {
        parts.push(<span key={`text-${idx}`}>{testText.slice(lastIndex, match.index!)}</span>);
      }
      parts.push(
        <mark
          key={`match-${idx}`}
          className="bg-yellow-200 text-slate-900 rounded px-0.5"
          title={`Match #${idx + 1}`}
        >
          {match[0]}
        </mark>
      );
      lastIndex = match.index! + match[0].length;
    });

    if (lastIndex < testText.length) {
      parts.push(<span key="text-end">{testText.slice(lastIndex)}</span>);
    }

    return <>{parts}</>;
  };

  return (
    <div className="space-y-10">
      <section className="space-y-6">
        <div className="max-w-3xl space-y-4">
          <p className="text-sm font-semibold uppercase tracking-[0.2em] text-primary">
            Browser-based Regex Tester
          </p>
          <h1 className="text-4xl font-bold tracking-tight text-text sm:text-5xl">
            Regex Tester — Test, Debug, and Understand Regular Expressions
          </h1>
          <p className="text-base leading-8 text-text/70">
            Test regular expressions in real time with match highlighting, group capture, and plain-English explanations.
          </p>
        </div>

        <div className="rounded-[28px] border border-black/6 bg-white p-4 shadow-sm sm:p-6 space-y-6">
          <div className="space-y-3">
            <p className="text-sm font-semibold text-text">Pattern</p>
            <input
              type="text"
              value={pattern}
              onChange={(e) => setPattern(e.target.value)}
              placeholder="Enter your regex pattern here"
              className={`w-full rounded-[24px] border px-4 py-3 text-sm font-mono outline-none transition-shadow focus:ring-4 focus:ring-primary/10 ${
                error ? "border-red-400 bg-red-50" : "border-black/8 bg-[#fbfcfd]"
              }`}
            />
            {error && (
              <div className="rounded-[18px] border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
                {error}
              </div>
            )}
          </div>

          <div className="flex flex-wrap gap-2">
            {FLAGS.map((flag) => (
              <label
                key={flag.key}
                className="inline-flex items-center gap-2 rounded-full border border-black/10 bg-white px-4 py-2 text-sm cursor-pointer hover:border-primary/20 hover:text-primary"
              >
                <input
                  type="checkbox"
                  checked={flags.includes(flag.key)}
                  onChange={() => toggleFlag(flag.key)}
                  className="h-4 w-4 rounded border-black/15 accent-primary"
                />
                {flag.label}
                <span className="text-xs text-text/60">({flag.description})</span>
              </label>
            ))}
          </div>

          <div className="space-y-3">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <p className="text-sm font-semibold text-text">Test Text</p>
              <button
                onClick={() => setTestText(SAMPLE_TEXT)}
                className="inline-flex items-center gap-2 rounded-full border border-black/10 bg-white px-3 py-1.5 text-xs font-semibold text-text transition-colors hover:border-primary/20 hover:text-primary"
              >
                Load Sample Text
              </button>
            </div>
            <div className="min-h-[180px] w-full rounded-[24px] border border-black/8 bg-[#fbfcfd] px-4 py-4 text-sm leading-7 text-slate-800">
              {highlightText()}
            </div>
            <textarea
              value={testText}
              onChange={(e) => setTestText(e.target.value)}
              placeholder="Paste your text here to test"
              spellCheck={false}
              className="min-h-[140px] w-full rounded-[24px] border border-black/8 bg-[#fbfcfd] px-4 py-4 text-sm leading-7 text-slate-800 outline-none transition-shadow focus:ring-4 focus:ring-primary/10"
            />
          </div>

          <div className="space-y-3">
            <div className="flex items-center gap-2">
              <span className="text-sm font-semibold text-text">Matches</span>
              <span className="rounded-full bg-emerald-100 text-emerald-800 px-3 py-1 text-xs font-semibold uppercase tracking-[0.18em]">
                {matches.length} match{matches.length !== 1 ? "es" : ""} found
              </span>
            </div>

            {matches.length > 0 && (
              <div className="space-y-3">
                {matches.map((match, matchIdx) => (
                  <div
                    key={matchIdx}
                    className="rounded-[20px] border border-black/6 bg-surface/70 p-4"
                  >
                    <p className="text-sm font-semibold text-text mb-2">Match #{matchIdx + 1}</p>
                    <div className="space-y-1">
                      <p className="text-sm font-mono text-text/70">Full match: "{match[0]}"</p>
                      {match.slice(1).map((group, groupIdx) => {
                        const name = Object.keys(match.groups || {}).find(
                          (n) => (match as any).groups[n] === group
                        );
                        return (
                          <p key={groupIdx} className="text-sm font-mono text-text/70">
                            {name ? `Group "${name}"` : `Group ${groupIdx + 1}`}: "{group}"
                          </p>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="rounded-[20px] border border-black/6 bg-surface/70 p-4 space-y-3">
            <p className="text-sm font-semibold text-text">Pattern Explanation</p>
            <ul className="space-y-1 list-disc list-inside text-sm text-text/70">
              {explanations.map((exp, idx) => (
                <li key={idx}>{exp}</li>
              ))}
            </ul>
          </div>

          <div className="space-y-3">
            <p className="text-sm font-semibold text-text">Common Patterns</p>
            <div className="flex flex-wrap gap-2">
              {COMMON_PATTERNS.map((p) => (
                <button
                  key={p.name}
                  onClick={() => loadPattern(p)}
                  className="inline-flex items-center gap-2 rounded-full border border-black/10 bg-white px-3 py-1.5 text-xs font-semibold text-text transition-colors hover:border-primary/20 hover:text-primary"
                >
                  {p.name}
                </button>
              ))}
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}

// Cron field definitions
const CRON_FIELDS = [
  { name: 'minute', min: 0, max: 59 },
  { name: 'hour', min: 0, max: 23 },
  { name: 'dayOfMonth', min: 1, max: 31 },
  { name: 'month', min: 1, max: 12 },
  { name: 'dayOfWeek', min: 0, max: 6 },
];

const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 
                     'July', 'August', 'September', 'October', 'November', 'December'];
const DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

// Validate a cron expression
export function validateCron(expr: string): { valid: boolean; error?: string } {
  const parts = expr.trim().split(/\s+/);
  if (parts.length !== 5) {
    return { valid: false, error: 'A cron expression must have exactly 5 fields' };
  }

  for (let i = 0; i < 5; i++) {
    const field = parts[i];
    const { name, min, max } = CRON_FIELDS[i];

    if (field === '*') continue;

    const partsList = field.split(',');
    for (const part of partsList) {
      if (part.includes('/')) {
        const [range, step] = part.split('/');
        if (!validateRange(range, min, max) || !validateNumber(step, 1, max)) {
          return { valid: false, error: `Invalid ${name} field: ${part}` };
        }
      } else if (part.includes('-')) {
        if (!validateRange(part, min, max)) {
          return { valid: false, error: `Invalid ${name} field: ${part}` };
        }
      } else {
        if (!validateNumber(part, min, max)) {
          return { valid: false, error: `Invalid ${name} field: ${part}` };
        }
      }
    }
  }

  return { valid: true };
}

function validateNumber(str: string, min: number, max: number): boolean {
  const num = parseInt(str, 10);
  return !isNaN(num) && num >= min && num <= max;
}

function validateRange(range: string, min: number, max: number): boolean {
  if (range === '*') return true;
  const [start, end] = range.split('-');
  if (end === undefined) {
    return validateNumber(start, min, max);
  }
  return validateNumber(start, min, max) && validateNumber(end, min, max) && parseInt(start) <= parseInt(end);
}

// Parse a cron field into human-readable parts
function parseField(field: string, fieldInfo: typeof CRON_FIELDS[0]): string {
  if (field === '*') {
    return `every ${fieldInfo.name}`;
  }

  const parts = field.split(',');
  const explanations: string[] = [];

  for (const part of parts) {
    if (part.includes('/')) {
      const [range, step] = part.split('/');
      if (range === '*') {
        explanations.push(`every ${step} ${fieldInfo.name}s`);
      } else {
        const [start, end] = range.split('-');
        explanations.push(`every ${step} ${fieldInfo.name}s from ${formatValue(start, fieldInfo.name)}${end ? ` to ${formatValue(end, fieldInfo.name)}` : ''}`);
      }
    } else if (part.includes('-')) {
      const [start, end] = part.split('-');
      explanations.push(`${formatValue(start, fieldInfo.name)} through ${formatValue(end, fieldInfo.name)}`);
    } else {
      explanations.push(formatValue(part, fieldInfo.name));
    }
  }

  return explanations.join(', ');
}

function formatValue(value: string, fieldName: string): string {
  if (fieldName === 'month') {
    return MONTH_NAMES[parseInt(value, 10) - 1];
  }
  if (fieldName === 'dayOfWeek') {
    return DAY_NAMES[parseInt(value, 10)];
  }
  return value;
}

// Generate a human-readable explanation
export function explainCron(expr: string): string {
  const parts = expr.trim().split(/\s+/);
  const explanations = parts.map((p, i) => parseField(p, CRON_FIELDS[i]));

  return `At ${explanations[0]}, ${explanations[1]}, ${explanations[2]}, ${explanations[3]}, ${explanations[4]}.`;
}

// Calculate next N run times
export function getNextRuns(expr: string, count = 5): Date[] {
  const { valid } = validateCron(expr);
  if (!valid) return [];

  const [minuteExpr, hourExpr, dayOfMonthExpr, monthExpr, dayOfWeekExpr] = expr.trim().split(/\s+/);

  const runs: Date[] = [];
  let current = new Date();
  current.setSeconds(0, 0);
  current.setMinutes(current.getMinutes() + 1); // Start from next minute

  while (runs.length < count && current.getTime() < Date.now() + 1000 * 60 * 60 * 24 * 365) { // Limit to 1 year
    if (matchesCron(current, minuteExpr, hourExpr, dayOfMonthExpr, monthExpr, dayOfWeekExpr)) {
      runs.push(new Date(current));
    }
    current.setMinutes(current.getMinutes() + 1);
  }

  return runs;
}

function matchesCron(date: Date, minute: string, hour: string, dayOfMonth: string, month: string, dayOfWeek: string): boolean {
  return matchesField(date.getMinutes(), minute, 0, 59) &&
         matchesField(date.getHours(), hour, 0, 23) &&
         matchesField(date.getDate(), dayOfMonth, 1, 31) &&
         matchesField(date.getMonth() + 1, month, 1, 12) &&
         matchesField(date.getDay(), dayOfWeek, 0, 6);
}

function matchesField(value: number, expr: string, min: number, max: number): boolean {
  if (expr === '*') return true;

  const parts = expr.split(',');
  return parts.some(part => {
    if (part.includes('/')) {
      const [range, stepStr] = part.split('/');
      const step = parseInt(stepStr, 10);
      if (range === '*') {
        return value % step === min % step;
      } else {
        const [start, end] = range.split('-').map(Number);
        return value >= start && (end ? value <= end : true) && (value - start) % step === 0;
      }
    } else if (part.includes('-')) {
      const [start, end] = part.split('-').map(Number);
      return value >= start && value <= end;
    } else {
      return value === parseInt(part, 10);
    }
  });
}

// Presets
export const CRON_PRESETS = [
  { label: 'Every minute', expr: '* * * * *' },
  { label: 'Every hour', expr: '0 * * * *' },
  { label: 'Every day at midnight', expr: '0 0 * * *' },
  { label: 'Every Monday at 9am', expr: '0 9 * * 1' },
  { label: 'Every 1st of month', expr: '0 0 1 * *' },
  { label: 'Every weekday at 6pm', expr: '0 18 * * 1-5' },
];

export function base64UrlDecode(input: string): string {
  let base64 = input.replace(/-/g, '+').replace(/_/g, '/');
  while (base64.length % 4) {
    base64 += '=';
  }
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new TextDecoder('utf-8').decode(bytes);
}

export function parseJwt(token: string): { header: any; payload: any; signature: string; rawHeader: string; rawPayload: string; rawSignature: string } {
  const parts = token.split('.');
  if (parts.length !== 3) {
    throw new Error('Invalid JWT format. A valid JWT must have 3 parts separated by dots.');
  }
  try {
    const header = JSON.parse(base64UrlDecode(parts[0]));
    const payload = JSON.parse(base64UrlDecode(parts[1]));
    return {
      header,
      payload,
      signature: parts[2],
      rawHeader: parts[0],
      rawPayload: parts[1],
      rawSignature: parts[2]
    };
  } catch (error) {
    throw new Error('Failed to parse JWT. The token appears to be malformed.');
  }
}

export function formatTimestamp(timestamp: number): string {
  try {
    return new Date(timestamp * 1000).toLocaleString();
  } catch {
    return 'Invalid timestamp';
  }
}

export function isExpired(payload: any): boolean | null {
  if (!payload || typeof payload.exp !== 'number') {
    return null;
  }
  return Date.now() > payload.exp * 1000;
}

export function isValidJwtFormat(token: string): boolean {
  const parts = token.trim();
  if (!parts) return false;
  const jwtParts = token.split('.');
  return jwtParts.length === 3;
}

export function downloadTextFile(content: string, fileName: string) {
  const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
  const objectUrl = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = objectUrl;
  link.download = fileName;
  link.click();
  URL.revokeObjectURL(objectUrl);
}

